theorem impl_trans (R : O → A → Prop) {P Q S : Set A}
    (h₁ : ImplicationHolds R P Q) (h₂ : ImplicationHolds R Q S) :
    ImplicationHolds R P S

theorem impl_union_left (R : O → A → Prop) {P₁ P₂ Q : Set A}
    (h₁ : ImplicationHolds R P₁ Q) :
    ImplicationHolds R (P₁ ∪ P₂) Q

theorem impl_inter_right (R : O → A → Prop) {P Q₁ Q₂ : Set A}
    (h₁ : ImplicationHolds R P Q₁) :
    ImplicationHolds R P (Q₁ ∩ Q₂)

theorem IsBasis.sound {R : O → A → Prop} {𝓛 : Set (Set A × Set A)}
    (h : IsBasis R 𝓛) {p : Set A × Set A} (hp : p ∈ 𝓛) :
    ImplicationHolds R p.1 p.2

theorem IsBasis.complete {R : O → A → Prop} {𝓛 : Set (Set A × Set A)}
    (h : IsBasis R 𝓛) {P Q : Set A} (hPQ : ImplicationHolds R P Q) :
    ∃ p ∈ 𝓛, p.1 ⊆ P ∧ Q ⊆ p.2

theorem threshExtent_antitone_attrs (μ : O → A → ℝ) (θ : ℝ) {B₁ B₂ : Set A}
    (h : B₁ ⊆ B₂) :
    threshExtent μ θ B₂ ⊆ threshExtent μ θ B₁

theorem threshIntent_antitone_objs (μ : O → A → ℝ) (θ : ℝ) {O₁ O₂ : Set O}
    (h : O₁ ⊆ O₂) :
    threshIntent μ θ O₂ ⊆ threshIntent μ θ O₁

theorem threshExtent_monotone_mu {μ₁ μ₂ : O → A → ℝ}
    (h : ∀ o a, μ₁ o a ≤ μ₂ o a) (θ : ℝ) (B : Set A) :
    threshExtent μ₁ θ B ⊆ threshExtent μ₂ θ B

theorem threshIntent_monotone_mu {μ₁ μ₂ : O → A → ℝ}
    (h : ∀ o a, μ₁ o a ≤ μ₂ o a) (θ : ℝ) (O' : Set O) :
    threshIntent μ₁ θ O' ⊆ threshIntent μ₂ θ O'

theorem bestPrefix_index_length {rest : List Char} {t : CharToken} {l₁ l₂ : List (List Char)}
    (h : rest.inits.reverse = l₁ ++ pieceOf t :: l₂) :
    l₁.length + (pieceOf t).length = rest.length

theorem bestPrefix_longer_candidate_fails {rest : List Char} {t : CharToken}
    (h : bestPrefix rest = some t) {u : List Char}
    (hup : u <+: rest) (hlt : (pieceOf t).length < u.length) :
    lookupTok u = none

theorem bestPrefix_pieceOf_mem_intent {rest : List Char} {t : CharToken}
    (h : bestPrefix rest = some t) :
    pieceOf t ∈ intent isPrefixRel ({rest} : Set (List Char))

theorem bestPrefix_pieceOf_mem_candidateSet {rest : List Char} {t : CharToken}
    (h : bestPrefix rest = some t) :
    pieceOf t ∈ candidateSet vocab rest
